cache   table dim_ads_${grass_region_without_quote} options ('storageLevel' 'MEMORY_AND_DISK_SER' ) as
select  ads_id
        ,placement
        ,main_product_type
        ,product_type
        ,sub_product_type
        ,case   when COALESCE(ads_id, -1) in (-1, 0) then CONCAT(cast(COALESCE(ads_id, -1) as STRING), '_', cast(FLOOR(RAND() * 20) as STRING))
                else cast(COALESCE(ads_id, -1) as STRING)
         end as salted_ads_id
from    (
    select  ads_id
            ,placement
            ,main_product_type
            ,product_type
            ,sub_product_type
            ,ROW_NUMBER() OVER (PARTITION BY ads_id ORDER BY placement DESC) AS rn
    from    mp_paidads.dim_advertise__reg_s0_live
    where   tz_type = 'local'
      and   grass_region = ${grass_region}
      and   grass_date = ${local_date}
) t
where   rn = 1
;

