--omni entry imp /click
create temporary view      omni_entry_all_type_imp_click_${grass_region_without_quote} as
select  business_line
        ,module
        ,object
        ,platform
        ,location
        ,is_ads
        ,ads_id
        ,main_product_type
        ,product_type
        ,sub_product_type
        ,sum(case when operation = 'impression' then 1 else 0 end) as omni_entry_impr_cnt
        ,sum(case when operation = 'click' then 1 else 0 end) as omni_entry_click_cnt
from    (
    select  T1.*
            ,coalesce(T3.main_product_type, 'others') as main_product_type
            ,COALESCE(T3.product_type, 'others') as product_type
            ,COALESCE(T3.sub_product_type, 'others') as sub_product_type
    from    (
        select  operation
                ,business_line
                ,module
                ,object
                ,platform
                ,case   when location_property.location is null then -1
                        else if(location_property.location >= 250, 250, location_property.location)
                 end as location
                ,common_property.is_ads as is_ads
                ,COALESCE(common_property.ads_id, -1) AS ads_id
                ,case   when COALESCE(common_property.ads_id, -1) IN (-1, 0) THEN CONCAT(CAST(COALESCE(common_property.ads_id, -1) AS STRING), '_', CAST(FLOOR(RAND() * 20) AS STRING))
                        ELSE CAST(COALESCE(common_property.ads_id, -1) AS STRING)
                 end as salted_ads_id
        from    traffic_omni_oa.dwd_scenario_event_log_di__reg_sensitive_live
        where   grass_date = ${local_date}
          and   grass_region = ${grass_region}
          and   tz_type = 'local'
          and   user_id > 0
          and   operation in ('impression', 'click')
          and   (
                        business_line = 'Homepage'
                    and module = 'Daily Discover'
                )
    ) as T1
    left join dim_ads_${grass_region_without_quote} as T3
    on      T1.salted_ads_id = T3.salted_ads_id
)
group by business_line, module, object, platform, location, is_ads, ads_id, main_product_type, product_type, sub_product_type
;

